#import <Foundation/Foundation.h>
#import <UIKit/UIKit.h>

int main() {
    @autoreleasepool {
        // Try to find the Open button in the key window and tap it
        UIWindow *keyWindow = [[UIApplication sharedApplication] keyWindow];

        // Recursive function to find buttons
        void (^findAndClickButton)(UIView *) = ^(UIView *view) {
            void (^searchView)(UIView *);
            searchView = ^(UIView *v) {
                if ([v isKindOfClass:[UIButton class]]) {
                    UIButton *button = (UIButton *)v;
                    NSString *title = [button titleForState:UIControlStateNormal];
                    if ([title isEqualToString:@"Open"]) {
                        [button sendActionsForControlEvents:UIControlEventTouchUpInside];
                        NSLog(@"Clicked Open button!");
                    }
                }
                for (UIView *subview in v.subviews) {
                    searchView(subview);
                }
            };
            searchView(v);
        };

        findAndClickButton(keyWindow);
        sleep(1);
    }
    return 0;
}
